pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public {
        c = new C();
        owner = address(this);
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= 500000000e18);

        // owner initializes balances
        vm.prank(owner);
        c.NETM();

        // burn some supply: totalDistributed decreases, balances[owner] does not
        vm.prank(owner);
        c.burn(amount);

        // owner re-runs distribution init
        vm.prank(owner);
        c.NETM();

        // General rule: after NETM(), the owner's credited balance equals totalDistributed().
        assertTrue(c.balanceOf(owner) == c.totalDistributed());
    }
}

