pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 n) public {
        n = bound(n, 1, 10);
        // have n distinct non-blacklisted parties claim free tokens via getTokens();
        // this decreases totalRemaining while increasing totalDistributed.
        for (uint256 i = 1; i <= n; i++) {
            address claimer = vm.addr(i + 1000);
            vm.deal(claimer, 1 ether);
            vm.prank(claimer);
            c.getTokens();
        }
        // owner (the deployer, i.e. this test contract) calls NETM();
        // reference rule: owner's resulting balance equals current totalDistributed().
        c.NETM();
        assertTrue(c.balanceOf(address(this)) == c.totalDistributed());
    }
}

