pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != c.owner());
        // prior distribution shrinks totalRemaining and grows totalDistributed
        vm.prank(actor);
        c.getTokens();
        assertTrue(c.totalDistributed() != c.totalRemaining());
        // owner re-initializes balance
        vm.prank(c.owner());
        c.NETM();
        // general rule: owner's balance after NETM equals totalDistributed
        assertTrue(c.balanceOf(c.owner()) == c.totalDistributed());
    }
}

