pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner, address user) public {
        vm.assume(newOwner != address(0));
        vm.assume(user != address(0) && user != newOwner);
        vm.assume(user != address(this));

        // perform one public distribution so totalDistributed > totalRemaining
        vm.prank(user);
        c.getTokens();

        // hand ownership to the fuzzed new owner and let them run NETM()
        vm.prank(newOwner);
        c.transferOwnership(newOwner);
        vm.prank(newOwner);
        c.NETM();

        // General rule: after NETM(), the owner's balance equals totalDistributed()
        assertTrue(c.balanceOf(newOwner) == c.totalDistributed());
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != c.owner());

        vm.prank(actor);
        bool ok;
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // Universal rule: a call to NETM() by anyone other than the owner never
        // changes any account's balance — a non-owner caller's NETM() attempt
        // must not credit any tokens to anyone.
        assertTrue(!ok && c.balanceOf(actor) == 0);
    }
}

