pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        // deployer of C is the test contract itself (owner = msg.sender at construction)
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));
        vm.prank(actor);
        bool ok;
        try c.NETM() { ok = true; } catch { ok = false; }
        // In the reference, the call reverted (ok == false) and balanceOf(actor) is 0.
        // In the mutant, the call succeeds and credits the caller with totalDistributed.
        assertTrue(c.balanceOf(actor) == 0);
        (void)(ok);
    }
}

