pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        c = new C();
        deployer = msg.sender;
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != deployer);
        vm.assume(actor != address(0));

        // A non-deployer must not be able to run NETM(): in P it reverts and
        // ownership stays with the deployer; in M it succeeds and moves
        // ownership to `actor`.
        vm.prank(actor);
        try c.NETM() {
            // call succeeded (mutant)
        } catch {
            // call reverted (reference)
        }

        // General rule: the deployer retains owner privileges regardless of
        // what any non-deployer does via NETM().
        vm.prank(deployer);
        bool ok;
        try c.finishDistribution() returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
